head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = 'ULDBNS10901.xml';
scwin.vMktactCd = "205";
scwin.pBndApplId = "";
scwin.vBndListProcsTpCd = "2";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.pBndApplId = arrPar[0].BND_APPL_ID;
    }
};



/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명       : 그리드 선택 시 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.pBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readIsuInfo';
    dts_IsuInfo.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);
    if (dts_IsuInfo.getTotalRow() > 0) {
        //물가연동채구분
        if (dts_IsuInfo.getCellData(1, 'ISUR_CD') == 'GB035') {
            cmb_InfllnkYn.setDisabled(false);
            edt_IsuDdRefIdx.setDisabled(false);
        } else {
            cmb_InfllnkYn.setDisabled(true);
            edt_IsuDdRefIdx.setDisabled(true);
        }
        //한글금액표기
        $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));

        //신용등급 SF
        if ($c.stf.getObjectValue(cmb_AsstSecutizTpCd) == '') {
            $c.stf.setObjectValue(cmb_SfValuYn1, '');
            $c.stf.setObjectValue(cmb_SfValuYn2, '');
            $c.stf.setObjectValue(cmb_SfValuYn3, '');
            $c.stf.setObjectValue(cmb_SfValuYn4, '');
            cmb_SfValuYn1.setDisabled(true);
            cmb_SfValuYn2.setDisabled(true);
            cmb_SfValuYn3.setDisabled(true);
            cmb_SfValuYn4.setDisabled(true);
        }
    }

    //기준금리상세(표면이자율,발행가액)
    dsNm = 'BNS_COUPNRT_ISURPRC';
    qryId = 'lds.stf.bnscommon.select.readCoupnRtAndIsurPrc';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CoupnRtAndIsurPrc, dsNm, qryId, param);

    //신용평가정보
    dsNm = 'BNS_CREDIT_INFO';
    qryId = 'lds.stf.bnscommon.select.listCredit';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);

    //인수기관정보
    dsNm = 'BNS_UDWRT_INST';
    qryId = 'lds.stf.bnscommon.select.listUdwrtInst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_UdwrtInst, dsNm, qryId, param);

    //원리금정보
    dsNm = 'BNS_PRINCINT_INFO';
    qryId = 'lds.stf.bnscommon.select.listPrincint';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Princint, dsNm, qryId, param);

    //CALL
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listOptionCall';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);

    //PUT
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listOptionPut';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);

    //변동금리
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listChgInt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);

    //유동화자산
    dsNm = 'BNS_SECUTIZ_ASST';
    qryId = 'lds.stf.bnscommon.select.listSecutizAsst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SecutizAsst, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    var dsNm = 'BNS_INST_INFO';
    var param = '&{P}V_INST_NM=';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_AsstHdTpCd, '03374'); //자산보유자 유형
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SecutizAsstTpCd, '03375'); //유동화자산 유형
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_CoupntRtCd, '03050'); //표면이자율결정 기준금리

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
