    arrCid.push({
        cid: '00872',
        cnm: 'cmb_IntPayMethdCd'
    }); //이자지급방법			
    arrCid.push({
        cid: '03075',
        cnm: 'cmb_AsstSecutizTpCd'
    }); //유동화					
    arrCid.push({
