    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyDdIntPayMethdCd'
    }); //휴무관련(이자)			
    arrCid.push({
        cid: '01513',
        cnm: 'cmb_CoupnPayMethdCd'
    }); //이자 선/후급			
    arrCid.push({
        cid: '03195',
        cnm: 'cmb_BndIntPayDdBasTpCd'
    }); //이자일지급구분			
    arrCid.push({
