/********************************************** 
 * 함수명   : fn_SetBasIntRtData
 * 설명       : 기준금리상세(표면이자율,발행가액) 데이터셋 설정
 ***********************************************/
scwin.fn_SetBasIntRtData = function() {
    if (dts_CoupnRtAndIsurPrc.getTotalRow() == 0) {
        //표면이자율
        var COUPN_RT_DECSN_BAS_INT_CD = $c.stf.getObjectValue(cmb_CoupnRtDecsnBasIntCd);
        var COUPN_RT_REMAIN_PD_CD = $c.stf.getObjectValue(cmb_CoupnRtRemainPdCd);
        var COUPN_RT_DECSN_SPD_SGN = $c.stf.getObjectValue(cmb_CoupnRtDecsnSpdSgn);
        var COUPN_RT_DECSN_SPD = $c.stf.getObjectValue(edt_CoupnRtDecsnSpd);
        var COUPN_RT_DECSN_BAS_DD = $c.stf.getObjectValue(edt_CoupnRtDecsnBasDd);
        var COUPN_RT_DECSN_TM = $c.stf.getObjectValue(cmb_CoupnRtDecsnTm);
        var COUPN_RT_MISC_BAS_INT_CONTN = $c.stf.getObjectValue(txb_CoupnRtMiscBasIntContn);
        //발행가액
        var ISU_PRC_DECSN_BAS_INT_CD = $c.stf.getObjectValue(cmb_IsuPrcDecsnBasIntCd);
        var ISU_PRC_DECSN_REMAIN_PD_CD = $c.stf.getObjectValue(cmb_IsuPrcDecsnRemainPdCd);
        var ISU_PRC_DECSN_SPD_SGN = $c.stf.getObjectValue(cmb_IsuPrcDecsnSpdSgn);
