        dts_CoupnRtAndIsurPrc.setCellData(idx, 'COUPN_RT_DECSN_TM', COUPN_RT_DECSN_TM);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'COUPN_RT_MISC_BAS_INT_CONTN', COUPN_RT_MISC_BAS_INT_CONTN);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'ISU_PRC_DECSN_BAS_INT_CD', ISU_PRC_DECSN_BAS_INT_CD);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'ISU_PRC_DECSN_REMAIN_PD_CD', ISU_PRC_DECSN_REMAIN_PD_CD);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'ISU_PRC_DECSN_SPD_SGN', ISU_PRC_DECSN_SPD_SGN);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'ISU_PRC_DECSN_SPD', ISU_PRC_DECSN_SPD);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'ISU_PRC_DECSN_BAS_DD', ISU_PRC_DECSN_BAS_DD);
        dts_CoupnRtAndIsurPrc.setCellData(idx, 'ISU_PRC_DECSN_TM', ISU_PRC_DECSN_TM);
