/********************************************** 
 * 함수명   : fn_SetSecutizAsstData
 * 설명       : 자산 데이터셋 설정
 ***********************************************/
scwin.fn_SetSecutizAsstData = function() {
    dts_SecutizAsst.removeAll();

    //1
    if ($c.stf.getObjectValue(cmb_AsstHdInstCd1) != '' ||
        $c.stf.getObjectValue(cmb_AsstHdTpCd1) != '' ||
        $c.stf.getObjectValue(cmb_AsstAdmInstCd1) != '' ||
        $c.stf.getObjectValue(cmb_SecutizAsstTpCd1) != '') {
        dts_SecutizAsst.insertRow();
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_APPL_ID', scwin.pBndApplId);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'HD_ASST_ORD', '1');
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_INST_CD', $c.stf.getObjectValue(cmb_AsstHdInstCd1));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_TP_CD', $c.stf.getObjectValue(cmb_AsstHdTpCd1));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_ADM_INST_CD', $c.stf.getObjectValue(cmb_AsstAdmInstCd1));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'SECUTIZ_ASST_TP_CD', $c.stf.getObjectValue(cmb_SecutizAsstTpCd1));
    }
    //2
    if ($c.stf.getObjectValue(cmb_AsstHdInstCd2) != '' ||
        $c.stf.getObjectValue(cmb_AsstHdTpCd2) != '' ||
        $c.stf.getObjectValue(cmb_AsstAdmInstCd2) != '' ||
        $c.stf.getObjectValue(cmb_SecutizAsstTpCd2) != '') {
        dts_SecutizAsst.insertRow();
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_APPL_ID', scwin.pBndApplId);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'HD_ASST_ORD', '2');
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_INST_CD', $c.stf.getObjectValue(cmb_AsstHdInstCd2));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_TP_CD', $c.stf.getObjectValue(cmb_AsstHdTpCd2));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_ADM_INST_CD', $c.stf.getObjectValue(cmb_AsstAdmInstCd2));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'SECUTIZ_ASST_TP_CD', $c.stf.getObjectValue(cmb_SecutizAsstTpCd2));
    }
    //3
    if ($c.stf.getObjectValue(cmb_AsstHdInstCd3) != '' ||
        $c.stf.getObjectValue(cmb_AsstHdTpCd3) != '' ||
        $c.stf.getObjectValue(cmb_AsstAdmInstCd3) != '' ||
        $c.stf.getObjectValue(cmb_SecutizAsstTpCd3) != '') {
        dts_SecutizAsst.insertRow();
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_APPL_ID', scwin.pBndApplId);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'HD_ASST_ORD', '3');
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_INST_CD', $c.stf.getObjectValue(cmb_AsstHdInstCd3));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_TP_CD', $c.stf.getObjectValue(cmb_AsstHdTpCd3));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_ADM_INST_CD', $c.stf.getObjectValue(cmb_AsstAdmInstCd3));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'SECUTIZ_ASST_TP_CD', $c.stf.getObjectValue(cmb_SecutizAsstTpCd3));
    }

    //4 기타체크
    if ($c.stf.getObjectValue(txb_AsstHdInstMiscContn) != '' ||
        $c.stf.getObjectValue(txb_AsstHdTpMiscContn) != '' ||
        $c.stf.getObjectValue(txb_AsstAdmInstMiscContn) != '' ||
        $c.stf.getObjectValue(txb_SecutizAsstTpMiscContn) != '') {
        dts_SecutizAsst.insertRow();
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_APPL_ID', vBndApplId);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'HD_ASST_ORD', '4');
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_INST_CD', 'ZZZZZ');
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_INST_MISC_CONTN', $c.stf.getObjectValue(txb_AsstHdInstMiscContn));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_HD_TP_MISC_CONTN', $c.stf.getObjectValue(txb_AsstHdTpMiscContn));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'ASST_ADM_INST_MISC_CONTN', $c.stf.getObjectValue(txb_AsstAdmInstMiscContn));
        dts_SecutizAsst.setCellData(dts_SecutizAsst.getRowPosition(), 'SECUTIZ_ASST_TP_MISC_CONTN', $c.stf.getObjectValue(txb_SecutizAsstTpMiscContn));
    }
};



