 * 함수명   : fn_SetCreditCombo
 * 설명       : 신용평가기관을 설정한다.
 ***********************************************/
scwin.fn_SetCreditCombo = function(obj, cd, val) {
    var cbdata = "^ ," + cd + "^" + val;
    obj.CBData = cbdata;
    $c.stf.setObjectValue(obj, cd);
};


/********************************************** 
 * 함수명   : fn_SetUdwrtInst
 * 설명       : 인수기관 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInst = function(rowIdx, cbObj, edtObj) {
    var UDWRT_INST_CD = dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD');
    if (UDWRT_INST_CD == '9999') {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    } else {
        $c.stf.setObjectValue(cbObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD'));
        $c.stf.setObjectValue(edtObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    }
};



/********************************************** 
 * 함수명   : fn_SetSecutizAsstTpCd
