 * 설명       : 발행기관 상태가 정상인지 확인한다.
 ***********************************************/
scwin.fn_chkInstAlert = function(selObj) {
    if ($c.stf.getObjectValue(selObj) == '') return;
    if ($c.bns.fn_ShowInstAlert(dts_InstCd, $c.cp.getNameValueRow(dts_InstCd, "INST_CD", $c.stf.getObjectValue(selObj))) > 0) {
        $c.stf.setObjectValue(selObj, '');
    }
};



/********************************************** 
 * 함수명   : fn_chkCall
 * 설명       : CALL 시작/종료일체크
 ***********************************************/
scwin.fn_chkCall = function() {
    for (var idx = 1; idx <= dts_OptionCall.getTotalRow(); idx++) {
        if (dts_OptionCall.getCellData(idx, 'CALL_EXER_STRT_DD').length != 8) {
            $c.win.alert('행사개시일을 입력하세요');
            return 1;
        } else if (dts_OptionCall.getCellData(idx, 'CALL_EXER_END_DD').length != 8) {
            $c.win.alert('행사종료일을 입력하세요');
            return 1;
        }
        if (dts_OptionCall.getCellData(idx, 'CALL_EXER_STRT_DD') > dts_OptionCall.getCellData(idx, 'CALL_EXER_END_DD')) {
            $c.win.alert('행사개시일을 행사종료일 이전으로 선택하세요');
            dts_OptionCall.setRowPosition(idx, 0);
            return 1;
        }
    }
    return 0;
};


/********************************************** 
 * 함수명   : fn_chkPut
 * 설명       : PUT 시작/종료일체크
 ***********************************************/
scwin.fn_chkPut = function() {
    for (var idx = 1; idx <= dts_OptionPut.getTotalRow(); idx++) {
        if (dts_OptionPut.getCellData(idx, 'PUT_EXER_STRT_DD').length != 8) {
            $c.win.alert('행사개시일을 입력하세요');
            return 1;
        } else if (dts_OptionPut.getCellData(idx, 'PUT_EXER_END_DD').length != 8) {
            $c.win.alert('행사종료일을 입력하세요');
            return 1;
        }
        if (dts_OptionPut.getCellData(idx, 'PUT_EXER_STRT_DD') > dts_OptionPut.getCellData(idx, 'PUT_EXER_END_DD')) {
            $c.win.alert('행사개시일을 행사종료일 이전으로 선택하세요');
            dts_OptionPut.setRowPosition(idx, 0);
            return 1;
        }
    }
    return 0;
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo);
    $c.stf.showObj(lbl_PopLoc, false); //팝업위치 레이블 숨김
    //호출파라미터설정
    scwin.fn_SetParam();

    //탭지정
    tab_Detail.setSelectedTabIndex(1);
    tab_SecutizAsst.setSelectedTabIndex(1);

    //패널라운드처리	
    $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
    $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
    $c.bns.BnsPanelToGroupBox(pnl_RelInst);
    $c.bns.BnsPanelToGroupBox(pnl_CoupnRt);
    $c.bns.BnsPanelToGroupBox(pnl_IsurPrc);
    $c.bns.BnsPanelToGroupBox(pnl_StockRel);
    $c.bns.BnsPanelToGroupBox(pnl_Princint);
    $c.bns.BnsPanelToGroupBox(pnl_Option);
    $c.bns.BnsPanelToGroupBox(pnl_ChgInt);
    $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);
    $c.bns.BnsPanelToGroupBox(pnl_SecutizAsst);
    $c.bns.BnsPanelToGroupBox(pnl_SecutizRelInst);
    $c.bns.BnsPanelToGroupBox(pnl_SecutizAsstMisc);
    $c.bns.BnsPanelToGroupBox(pnl_Strip);
    $c.bns.BnsPanelToGroupBox(pnl_Els);

    //탭설정
    scwin.fn_SetDtlTab();
    //콤보설정
    scwin.fn_SetComboCode();

    //종목조회
    scwin.fn_dtl_sync();
    scwin.vRowCount = dts_IsuInfo.getTotalRow();
    //물가연동채구분
    if (dts_IsuInfo.getCellData(1, 'ISUR_CD') == 'GB035') {
        cmb_InfllnkYn.setDisabled(false);
        edt_IsuDdRefIdx.setDisabled(false);
    } else {
        cmb_InfllnkYn.setDisabled(true);
        edt_IsuDdRefIdx.setDisabled(true);
    }
};
