scwin.txb_UnqIsuEngNm_onkeyup = function() {
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_UnqIsuEngNm) + ' ';
    for (var i = 0; i < str.length - 1; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('한글은 사용할 수 없습니다');
            $c.stf.setObjectValue(txb_UnqIsuEngNm, str.substring(0, str.length - 2));
        }
    }
};
scwin.dts_OptionCall_OnColumnChanged = function(row, colid) {
    if (row > 0) {
        if (dts_OptionCall.getCellData(row, 'CALL_EXER_STRT_DD') != '' &&
            dts_OptionCall.getCellData(row, 'CALL_EXER_END_DD') != '') {
            scwin.fn_chkCall();
        }
    }
};
