    //ELB/DLB 일 경우 옵션설정
    if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '3' ||
        $c.stf.getObjectValue(cmb_NusualBndTpCd) == '4') {
        var cd = '';
        if ($c.stf.getObjectValue(cmb_RghtTpCd) == 'C') cd = '1';

        else if ($c.stf.getObjectValue(cmb_RghtTpCd) == 'P') cd = '2';

        else if ($c.stf.getObjectValue(cmb_RghtTpCd) == 'A') cd = '3';
        $c.stf.setObjectValue(cmb_ImbdoptCorpbndCd, cd);
    }
};
